class Graph:
    """Class representing a directed graph for Bellman-Ford execution."""

    def __init__(self, vertices_count):
        self.vertices_count = vertices_count
        self.edges = []

    def add_edge(self, source, destination, weight):
        """Add a directed weighted edge to the graph."""
        self.edges.append([source, destination, weight])

    def print_iteration_table(self, distances, predecessors, iteration_num):
        """Print the distance and predecessor states for each iteration."""
        print(f"\n--- Iteration {iteration_num} ---")

        vertices = [str(i) for i in range(self.vertices_count)]
        header = "Vertex:\t\t" + "\t".join(vertices)

        formatted_dist = [
            str(d) if d != float("Inf") else "INF" for d in distances
        ]
        dist_row = "Distance:\t" + "\t".join(formatted_dist)

        formatted_pred = [
            str(p) if p is not None else "-" for p in predecessors
        ]
        pred_row = "Predecessor:\t" + "\t".join(formatted_pred)

        print(header)
        print(dist_row)
        print(pred_row)

    def bellman_ford(self, source_vertex):
        """Execute Bellman-Ford to find shortest paths and cycles."""
        # Step 1: Initialize distances as infinite and predecessors as None.
        distances = [float("Inf")] * self.vertices_count
        predecessors = [None] * self.vertices_count
        distances[source_vertex] = 0

        # Print the initial state before any relaxation (Iteration 0).
        self.print_iteration_table(distances, predecessors, 0)

        # Step 2: Relax all edges |V| - 1 times.
        for i in range(1, self.vertices_count):
            for source, destination, weight in self.edges:
                if (distances[source] != float("Inf") and
                        distances[source] + weight < distances[destination]):
                    distances[destination] = distances[source] + weight
                    predecessors[destination] = source

            # Print the table after each full relaxation step.
            self.print_iteration_table(distances, predecessors, i)

        # Step 3: Check for negative-weight cycles.
        has_negative_cycle = False
        for source, destination, weight in self.edges:
            if (distances[source] != float("Inf") and
                    distances[source] + weight < distances[destination]):
                has_negative_cycle = True
                break

        print("\n-----------------------------------------")
        if has_negative_cycle:
            print("Result: Graph contains a negative weight cycle!")
        else:
            print("Result: No negative weight cycle detected.")


# Constructing the graph from the second image.
# Total vertices = 5 (numbered from 0 to 4).
graph = Graph(5)
graph.add_edge(0, 1, 5)
graph.add_edge(1, 2, 1)
graph.add_edge(1, 3, 2)
graph.add_edge(2, 4, 1)
graph.add_edge(4, 3, -1)

# Run the algorithm starting from vertex 0.
graph.bellman_ford(0)